  transform: translateY(0);
}

.wt-layout-finbiz .progress-wrap::after {
  position: absolute;
  font-family: "unicons";
  content: "\e84b";
  text-align: center;
  line-height: 46px;
  font-size: 24px;
  color: var(--color-primary);
  left: 0;
  top: 0;
  height: 46px;
  width: 46px;
  cursor: pointer;
  display: block;
  z-index: 1;
  -webkit-transition: all 200ms linear;
  transition: all 200ms linear;
  border: 2px solid var(--color-primary);
  box-shadow: none;
  border-radius: 50% !important;
  border-radius: 5px;
}

.wt-layout-finbiz .progress-wrap:hover::after {
  opacity: 1;
  content: "\e84b";
  border: 2px solid var(--color-primary);
}

.wt-layout-finbiz .progress-wrap::before {
  position: absolute;
  font-family: "unicons";
  content: "\e84b";
  text-align: center;
  line-height: 46px;
  font-size: 24px;
  opacity: 0;
  background: var(--color-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  left: 0;
  top: 0;
  height: 46px;
  width: 46px;
  cursor: pointer;
  display: block;
  z-index: 2;
  -webkit-transition: all 200ms linear;
  transition: all 200ms linear;
}

.wt-layout-finbiz .progress-wrap:hover::before {
  opacity: 0;
