.wt-layout-finbiz .loader-wrapper {
  --line-width: 5px;
  --curtain-color: #ffffff;
  --outer-line-color: #dca8a8;
  --middle-line-color: #ff0000;
  --inner-line-color: #cf1414;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1000;
}

.wt-layout-finbiz .loader {
  display: block;
  position: relative;
  top: 50%;
  left: 50%;
  width: 150px;
  height: 150px;
  margin: -75px 0 0 -75px;
  border: var(--line-width) solid transparent;
  border-top-color: var(--outer-line-color);
  border-radius: 100%;
  -webkit-animation: wt-finbiz-spin 2s linear infinite;
  animation: wt-finbiz-spin 2s linear infinite;
  z-index: 1001;
}

.wt-layout-finbiz .loader:before {
  content: "";
  position: absolute;
  top: 4px;
  left: 4px;
  right: 4px;
  bottom: 4px;
  border: var(--line-width) solid transparent;
  border-top-color: var(--inner-line-color);
  border-radius: 100%;
  -webkit-animation: wt-finbiz-spin 3s linear infinite;
  animation: wt-finbiz-spin 3s linear infinite;
}

.wt-layout-finbiz .loader:after {
  content: "";
  position: absolute;
  top: 14px;
  left: 14px;
  right: 14px;
  bottom: 14px;
  border: var(--line-width) solid transparent;
  border-top-color: var(--middle-line-color);
  border-radius: 100%;
  -webkit-animation: wt-finbiz-spin 1.5s linear infinite;
  animation: wt-finbiz-spin 1.5s linear infinite;
}

@-webkit-keyframes wt-finbiz-spin {
  0% {
    -webkit-transform: rotate(0deg);
    -ms-transform: rotate(0deg);
    transform: rotate(0deg);
  }
  100% {
    -webkit-transform: rotate(360deg);
    -ms-transform: rotate(360deg);
    transform: rotate(360deg);
  }
}
@keyframes wt-finbiz-spin {
  0% {
    -webkit-transform: rotate(0deg);
    -ms-transform: rotate(0deg);
    transform: rotate(0deg);
  }
  100% {
    -webkit-transform: rotate(360deg);
    -ms-transform: rotate(360deg);
    transform: rotate(360deg);
  }
}
